const label = "module";          // module scope.

function report() {
  const label = "function";      // shadows module label here.
  if (true) {
    const label = "block";       // shadows again, only in this block.
    console.log(label);          // "block"
  }
  console.log(label);            // "function"
}
report();
console.log(label);              // "module"

// Temporal dead zone.
{
  // console.log(total);  ReferenceError: before initialization.
  let total = 10;
  console.log(total);            // 10
}
```

| Keyword | Scope | Use before declaration |
|---|---|---|
| `let` / `const`. | nearest block. | ReferenceError (TDZ). |
| `var`. | whole function. | undefined (hoisted). |
| function declaration. | enclosing block/function. | callable (hoisted). |

